def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = set()
    panels = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            panels.append(cells)

    boxes = []
    for cells in panels:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        boxes.append((r0, c0, r1, c1))

    canvas = min(boxes, key=lambda b: (b[0], -b[1]))
    color = grid[canvas[0]][canvas[1]]
    out = [[color for _ in range(6)] for _ in range(6)]
    for r0, c0, r1, c1 in boxes:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] != color:
                    out[r - r0][c - c0] = grid[r][c]
    return out
